/// The elementary functions of `float`, `double` (Track M milestone 2) and `long double`
/// (milestone 5a; `_Float128` follows, and with it the family tests): each name of those formats
/// is exported, and the translation layer reports the result, the flags and errno of the
/// implementation.
#[test]
fn elementary_float_double_and_long_double_members() {
    // Clauses: s10_3_c_0, s10_0_c_0.
    let families = [
        "exp", "exp2", "exp10", "expm1", "log", "log2", "log10", "log1p", "pow", "cbrt", "sin", "cos", "tan", "sincos", "asin", "acos",
        "atan", "atan2", "sinh", "cosh", "tanh", "asinh", "acosh", "atanh",
    ];
    for base in families {
        for suffix in ["", "f", "f32", "f64", "f32x", "l", "f64x"] {
            products::math_exported(&format!("{base}{suffix}"));
        }
    }
    assert_eq!(observe(|| assert_eq!(m::exp(0.0), 1.0)), (0, Flags(0)));
    let one = (0x3fffu128 << 64) | (1u128 << 63);
    assert_eq!(observe(|| assert_eq!(m::liella_expl_bits(LdBits::from_bits(0)).to_bits(), one)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_exp2f64x_bits(LdBits::from_bits((0x4fffu128 << 64) | (1u128 << 63))).to_bits(), (0x7fffu128 << 64) | (1u128 << 63))), (34, Flags(0x28)));
    assert_eq!(observe(|| assert_eq!(m::liella_log2l_bits(LdBits::from_bits(0)).to_bits(), (0xffffu128 << 64) | (1u128 << 63))), (34, Flags::DIVBYZERO));
    assert_eq!(observe(|| assert_eq!(m::liella_powl_bits(LdBits::from_bits(one + (1u128 << 64)), LdBits::from_bits(one + (3u128 << 64))).to_bits(), (0x4007u128 << 64) | (1u128 << 63))), (0, Flags(0))); // 2^8 = 256
    let (mut sl, mut cl) = (LdBits::from_bits(9), LdBits::from_bits(9));
    assert_eq!(observe(|| m::liella_sincosl_bits(LdBits::from_bits(0), Some(&mut sl), Some(&mut cl))), (0, Flags(0)));
    assert_eq!((sl.to_bits(), cl.to_bits()), (0, one));
    assert_eq!(observe(|| assert!(m::expf(100.0).is_infinite())), (34, Flags(0x28))); // ERANGE, overflow
    assert_eq!(observe(|| assert_eq!(m::exp(-1000.0), 0.0)), (34, Flags(0x30))); // ERANGE, underflow
    assert_eq!(observe(|| assert!(m::log(-1.0).is_nan())), (33, Flags::INVALID)); // EDOM
    assert_eq!(observe(|| assert_eq!(m::log2f(0.0), f32::NEG_INFINITY)), (34, Flags::DIVBYZERO));
    assert_eq!(observe(|| assert_eq!(m::pow(2.0, 10.0), 1024.0)), (0, Flags(0)));
    assert_eq!(observe(|| assert!(m::acosf32(2.0).is_nan())), (33, Flags::INVALID));
    assert_eq!(observe(|| assert_eq!(m::atanhf64(-1.0), f64::NEG_INFINITY)), (34, Flags::DIVBYZERO));
    let (mut s, mut c) = (9.0, 9.0);
    assert_eq!(observe(|| m::sincos(0.0, Some(&mut s), Some(&mut c))), (0, Flags(0)));
    assert_eq!((s, c), (0.0, 1.0));
    let (mut sf, mut cf) = (0.0f32, 0.0f32);
    assert_eq!(observe(|| m::sincosf(f32::INFINITY, Some(&mut sf), Some(&mut cf))), (33, Flags::INVALID));
    assert!(sf.is_nan() && cf.is_nan());
    fpu::clear(&CSys, Flags::ALL);
}

/// The special functions of `float`, `double` (Track M milestone 3) and `long double`
/// (milestone 5b; `_Float128` follows, and with it the family tests): each name of those formats
/// is exported, `lgamma` and `gamma` store the sign of Γ(x) in `signgam` and `lgamma_r` through
/// its pointer.
#[test]
fn special_float_double_and_long_double_members() {
    // Clauses: s10_3_c_0, s10_0_c_0.
    for base in ["erf", "erfc", "tgamma", "lgamma", "j0", "j1", "y0", "y1", "jn", "yn"] {
        for suffix in ["", "f", "f32", "f64", "f32x", "l", "f64x"] {
            products::math_exported(&format!("{base}{suffix}"));
        }
    }
    for n in ["gamma", "gammaf", "gammal"] {
        products::math_exported(n);
    }
    products::math_exported("signgam");
    products::math_exported("__signgam");
    use core::sync::atomic::Ordering::Relaxed;
    let sg = || liella_boundary::data::signgam.load(Relaxed);
    let v = m::lgamma(-0.5);
    assert!((v - 1.265_512_123_484_645_3).abs() < 1e-15 && sg() == -1);
    assert_eq!(m::gammaf(3.0), core::f32::consts::LN_2);
    assert_eq!(sg(), 1);
    let mut s = 0;
    assert!(m::lgamma_r(-1.5, Some(&mut s)) > 0.0 && s == 1);
    assert_eq!(sg(), 1, "lgamma_r leaves signgam");
    assert_eq!(observe(|| assert!(m::tgamma(-2.0).is_nan())), (33, Flags::INVALID)); // EDOM
    assert_eq!(observe(|| assert_eq!(m::tgamma(5.0), 24.0)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::lgamma(0.0), f64::INFINITY)), (34, Flags::DIVBYZERO));
    assert_eq!(observe(|| assert_eq!(m::y0(0.0), f64::NEG_INFINITY)), (34, Flags::DIVBYZERO));
    assert_eq!(observe(|| assert!(m::y1f(-1.0).is_nan())), (33, Flags::INVALID));
    assert_eq!(observe(|| assert_eq!(m::ynf32(3, 0.0), f32::NEG_INFINITY)), (34, Flags::DIVBYZERO));
    assert_eq!(observe(|| assert_eq!(m::jn(-3, 0.5), -m::jn(3, 0.5))), (0, Flags::INEXACT));
    assert_eq!(observe(|| assert_eq!(m::erfc(f64::NEG_INFINITY), 2.0)), (0, Flags(0)));
    // long double: through the bit-level forwarders the C wrappers call.
    let ld = |e: u128, sig: u64| LdBits::from_bits((e << 64) | u128::from(sig));
    let (one, half, neg_half) = (ld(0x3fff, 1 << 63), ld(0x3ffe, 1 << 63), ld(0xbffe, 1 << 63));
    assert_eq!(observe(|| assert_eq!(m::liella_tgammal_bits(ld(0x4001, 5 << 61)).to_bits(), ld(0x4003, 3 << 62).to_bits())), (0, Flags(0))); // Γ(5) = 24
    assert_eq!(observe(|| assert!(m::liella_lgammal_bits(neg_half).to_bits() > half.to_bits())), (0, Flags::INEXACT));
    assert_eq!(sg(), -1);
    let mut s = 0;
    assert_eq!(observe(|| assert_eq!(m::liella_lgammaf64x_r_bits(one, Some(&mut s)).to_bits(), 0)), (0, Flags(0)));
    assert_eq!((s, sg()), (1, -1), "lgammal_r leaves signgam");
    assert_eq!(observe(|| assert_eq!(m::liella_gammal_bits(ld(0xbfff, 1 << 63)).to_bits(), ld(0x7fff, 1 << 63).to_bits())), (34, Flags::DIVBYZERO)); // pole at −1
    assert_eq!(sg(), 1);
    assert_eq!(observe(|| assert_eq!(m::liella_erfcl_bits(ld(0xffff, 1 << 63)).to_bits(), ld(0x4000, 1 << 63).to_bits())), (0, Flags(0))); // erfc(−∞) = 2
    assert_eq!(observe(|| assert_eq!(m::liella_y0l_bits(LdBits::from_bits(0)).to_bits(), ld(0xffff, 1 << 63).to_bits())), (34, Flags::DIVBYZERO));
    assert_eq!(observe(|| assert_eq!(m::liella_j0f64x_bits(LdBits::from_bits(0)).to_bits(), one.to_bits())), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_ynl_bits(2, ld(0xbfff, 1 << 63)).to_bits() >> 64, 0x7fff)), (33, Flags::INVALID)); // EDOM
    assert_eq!(observe(|| assert_eq!(m::liella_jnl_bits(-3, half).to_bits(), m::liella_jnl_bits(3, half).to_bits() ^ (1 << 79))), (0, Flags::INEXACT));
    // Γ(1756) is above LDBL_MAX: ERANGE with overflow.
    assert_eq!(observe(|| assert_eq!(m::liella_tgammal_bits(ld(0x4009, 0xdb80_0000_0000_0000)).to_bits(), ld(0x7fff, 1 << 63).to_bits())), (34, Flags(0x28)));
    fpu::clear(&CSys, Flags::ALL);
}

/// The complex functions of `float` and `double` (Track M milestone 4; the `long double` and
/// `_Float128` members follow in milestone 5, and with them the family tests): each name of
/// those formats is exported, both parts travel as the C ABI passes a complex value, and the
/// translation layer reports the flags and errno of the implementation.
#[test]
fn complex_float_and_double_members() {
    // Clauses: s10_5_c_0, s10_0_c_0.
    let families = [
        "cabs", "carg", "creal", "cimag", "conj", "cproj", "cexp", "clog", "clog10", "cpow", "csqrt", "csin", "ccos", "ctan", "csinh", "ccosh",
        "ctanh", "casin", "cacos", "catan", "casinh", "cacosh", "catanh",
    ];
    for base in families {
        for suffix in ["", "f", "f32", "f64", "f32x"] {
            products::math_exported(&format!("{base}{suffix}"));
        }
    }
    products::math_exported("__clog10");
    products::math_exported("__clog10f");
    use liella_boundary::mathret::Complex;
    let z = |re: f64, im: f64| Complex { re, im };
    let zf = |re: f32, im: f32| Complex { re, im };
    assert_eq!(observe(|| assert_eq!(m::csqrt(z(-4.0, 0.0)), z(0.0, 2.0))), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::cabsf(zf(3.0, 4.0)), 5.0)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::cargf32(zf(-1.0, 0.0)), core::f32::consts::PI)), (0, Flags::INEXACT));
    assert_eq!(observe(|| assert_eq!(m::creal(z(1.5, -2.5)), 1.5)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::cimagf64(z(1.5, -2.5)), -2.5)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::conjf(zf(1.0, 2.0)), zf(1.0, -2.0))), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::clog(z(0.0, 0.0)).re, f64::NEG_INFINITY)), (34, Flags::DIVBYZERO)); // ERANGE
    assert_eq!(observe(|| assert!(m::cexp(z(800.0, 0.5)).re.is_infinite())), (34, Flags(0x28))); // ERANGE, overflow
    assert_eq!(observe(|| assert!(m::cexpf32x(z(0.0, f64::INFINITY)).re.is_nan())), (33, Flags::INVALID)); // EDOM
    assert_eq!(observe(|| assert_eq!(m::cpow(z(1.0, 1.0), z(2.0, 0.0)), z(0.0, 2.0))), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::__clog10(z(100.0, 0.0)), z(2.0, 0.0))), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::catanh(z(1.0, 0.0)).re, f64::INFINITY)), (34, Flags::DIVBYZERO));
    fpu::clear(&CSys, Flags::ALL);
}

/// The complex forwarders of `long double`, `_Float64x` and `_Float128` (D-10.21): each name is
/// exported, and the bit-level functions behind the C forwarders keep the parts in their order
/// and report the flags of the implementation.
#[test]
fn complex_long_double_and_float128_forwarded_members() {
    // Clauses: s10_5_c_0, s10_0_c_0.
    for base in ["cabs", "creal", "cimag", "conj", "cproj"] {
        for suffix in ["l", "f64x", "f128"] {
            products::math_exported(&format!("{base}{suffix}"));
        }
    }
    products::math_exported("cargl");
    products::math_exported("cargf64x");
    use liella_abi::ctypes::F128Bits;
    use liella_boundary::mathret::Complex;
    let ld = |e: u128, sig: u64| LdBits::from_bits((e << 64) | u128::from(sig));
    let q = |hi: u64| F128Bits::from_bits(u128::from(hi) << 64);
    let (one, two, neg_two, inf) = (ld(0x3fff, 1 << 63), ld(0x4000, 1 << 63), ld(0xc000, 1 << 63), ld(0x7fff, 1 << 63));
    let z = Complex { re: one, im: two };
    assert_eq!(observe(|| assert_eq!(m::liella_creall_bits(z), one)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_cimagf64x_bits(z), two)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_conjl_bits(z), Complex { re: one, im: neg_two })), (0, Flags(0)));
    // cproj(1 − i∞) = +∞ − i0.
    let p = Complex { re: one, im: ld(0xffff, 1 << 63) };
    assert_eq!(observe(|| assert_eq!(m::liella_cprojf64x_bits(p), Complex { re: inf, im: ld(0x8000, 0) })), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_cprojl_bits(z), z)), (0, Flags(0)));
    let (three, four, five) = (ld(0x4000, 3 << 62), ld(0x4001, 1 << 63), ld(0x4001, 5 << 61));
    assert_eq!(observe(|| assert_eq!(m::liella_cabsl_bits(Complex { re: three, im: four }), five)), (0, Flags(0)));
    // carg(−1 + i0) = π, rounded to nearest.
    let minus_one = Complex { re: ld(0xbfff, 1 << 63), im: ld(0, 0) };
    assert_eq!(observe(|| assert_eq!(m::liella_cargl_bits(minus_one), ld(0x4000, 0xc90f_daa2_2168_c235))), (0, Flags::INEXACT));
    let w = Complex { re: q(0x3fff_0000_0000_0000), im: q(0x4000_0000_0000_0000) };
    assert_eq!(observe(|| assert_eq!(m::liella_crealf128_bits(w), w.re)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_cimagf128_bits(w), w.im)), (0, Flags(0)));
    assert_eq!(observe(|| assert_eq!(m::liella_conjf128_bits(w), Complex { re: w.re, im: q(0xc000_0000_0000_0000) })), (0, Flags(0)));
    let three_four = Complex { re: q(0x4000_8000_0000_0000), im: q(0x4001_0000_0000_0000) };
    assert_eq!(observe(|| assert_eq!(m::liella_cabsf128_bits(three_four), q(0x4001_4000_0000_0000))), (0, Flags(0)));
    let qinf = Complex { re: q(0xffff_0000_0000_0000), im: q(0x8000_0000_0000_0000) };
    assert_eq!(observe(|| assert_eq!(m::liella_cprojf128_bits(qinf), Complex { re: q(0x7fff_0000_0000_0000), im: q(0x8000_0000_0000_0000) })), (0, Flags(0)));
    fpu::clear(&CSys, Flags::ALL);
}

/// `hypotf` in MXCSR direction `rc` (0 nearest, 1 down, 2 up, 3 toward zero): the result's bits,
/// the IEEE flags it raised (the denormal-operand bit aside) and `errno`.
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn hypotf_in(rc: u32, f: impl FnOnce() -> f32) -> (u64, u32, i32) {
    liella_boundary::errno::set_raw(0);
    let (v, after) = around(0x1f80 | rc << 13, || u64::from(f().to_bits()));
    (v, after & 0x3d, liella_boundary::errno::get())
}

#[test]
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn math_hypotf_fast_path_is_the_accurate_hypotf() {
    // Clauses: s10_0_f_0, s10_0_c_0. #1541: the fast path's bits, flags and errno are the
    // correctly rounded path's in every direction (exact roots included: they raise nothing);
    // roots on a float midpoint, overflow, subnormal results and NaN/infinity operands reach
    // the accurate path.
    use liella_boundary::mathret as mr;
    let mut pairs: Vec<(f32, f32)> = vec![
        (3.0, 4.0), (-7.0, 24.0), (1.0, 1.0), (f32::MAX, f32::MAX), (f32::MAX, 1.0), (1.0, 2f32.powi(-12)),
        (f32::MIN_POSITIVE, f32::MIN_POSITIVE), (1e-45, 1e-45), (5e-39, 3e-39), (0.0, -0.0),
        (f32::INFINITY, f32::NAN), (f32::NAN, 1.0), (1e30, 1e-30), (2.5e19, 2.5e19), (1.8e19, 1.8e19),
    ];
    // The rounding boundary: roots within one double ulp of a float midpoint m (x in [1, 2),
    // y near 2^-11.5 x^(1/2), found by an exact integer search). x^2 + y^2 rounds to m^2 in
    // nearest, the double root is m exactly and ties-to-even picks the wrong float: only the
    // exact-midpoint test sends these to the accurate path (true root above m for the 1st and 3rd pair,
    // below for the 2nd and 4th).
    for (xb, yb) in [(0x3f80_0072u32, 0x39b5_0544u32), (0x3f80_0083, 0x39b5_0550), (0x3f80_01fe, 0x39b5_065c), (0x3f80_0261, 0x39b5_06a2)] {
        pairs.push((f32::from_bits(xb), f32::from_bits(yb)));
        pairs.push((-f32::from_bits(yb), f32::from_bits(xb)));
    }
    let mut s: u64 = 0x9e37_79b9_7f4a_7c15;
    for i in 0..40_000u32 {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        let (a, b) = ((s >> 32) as u32, s as u32);
        // Every third pair shares the first operand's exponent: the sum then rounds least.
        pairs.push(if i % 3 == 0 { (f32::from_bits(a), f32::from_bits((a & 0xff80_0000) | (b & 0x7f_ffff))) } else { (f32::from_bits(a), f32::from_bits(b)) });
    }
    // The fast-path rate is counted over operands of comparable magnitude (biased exponents
    // within 8 of each other, 2..=0xfd: the root is then a normal float). Operands further
    // apart make y² vanish in x² + y² (the double root is then |x| or its neighbour, still
    // decided on the fast path), but they are most random bit-pattern pairs and would swamp the rate.
    let comparable = |x: f32, y: f32| {
        let (ex, ey) = ((x.to_bits() >> 23) & 0xff, (y.to_bits() >> 23) & 0xff);
        (2..=0xfd).contains(&ex) && (2..=0xfd).contains(&ey) && ex.abs_diff(ey) <= 8
    };
    let (mut fast, mut eligible) = (0usize, 0usize);
    for rc in 0..4u32 {
        for &(x, y) in &pairs {
            let got = hypotf_in(rc, || m::hypotf(x, y));
            let want = hypotf_in(rc, || mr::ret(liella_math::pow::hypot(x, y, mr::mode())));
            assert_eq!(got, want, "hypotf({x:e}, {y:e}) in direction {rc}");
            if comparable(x, y) {
                eligible += 1;
                if hypotf_in(rc, || mr::hypotf_fast(x, y).unwrap_or(f32::NAN)).0 == got.0 {
                    fast += 1;
                }
            }
        }
    }
    assert_eq!(hypotf_in(0, || m::hypotf(3.0, 4.0)), (u64::from(5f32.to_bits()), 0, 0));
    assert_eq!(hypotf_in(0, || m::hypotf(f32::MAX, f32::MAX)), (u64::from(f32::INFINITY.to_bits()), 0x28, 34));
    // #1561, settled by a black-box probe of the reference (glibc 2.39): toward zero and
    // downward the overflowing root rounds to FLT_MAX with overflow and inexact raised and
    // errno left 0; upward a root just above FLT_MAX is infinity with ERANGE.
    let fmax = u64::from(f32::MAX.to_bits());
    assert_eq!(hypotf_in(3, || m::hypotf(f32::MAX, f32::MAX)), (fmax, 0x28, 0));
    assert_eq!(hypotf_in(1, || m::hypotf(f32::MAX, f32::MAX)), (fmax, 0x28, 0));
    assert_eq!(hypotf_in(3, || m::hypotf(f32::MAX, 1.0)), (fmax, 0x20, 0));
    assert_eq!(hypotf_in(2, || m::hypotf(f32::MAX, 1.0)), (u64::from(f32::INFINITY.to_bits()), 0x28, 34));
    // Finite random operands of comparable magnitude overwhelmingly take the fast path.
    assert!(eligible > 40_000 && fast * 10 > eligible * 9, "fast path taken {fast} of {eligible} comparable");
    fpu::clear(&CSys, Flags::ALL);
}

/// Whether `f` is √(x²+y²) rounded in MXCSR direction `rc` (0 nearest, 1 down, 2 up, 3 toward
/// zero): the root inside the rounding interval, or exactly `f` (an exact root), decided in
/// integers: the squares of the interval ends against x²+y², in units of a quarter `f` ulp.
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn hypotf_oracle(x: f32, y: f32, f: f32, rc: u32) -> bool {
    let parts = |v: f32| -> (u128, i32) {
        let b = v.to_bits() & 0x7fff_ffff;
        let (e, m) = ((b >> 23) as i32, u128::from(b & 0x7f_ffff));
        if e == 0 { (m, -149) } else { (m | 0x80_0000, e - 150) }
    };
    let (mf, ef) = parts(f);
    if f.to_bits() >> 23 == 0 || f.to_bits() >> 23 >= 0xff {
        return false; // the fast path returns positive normal floats only
    }
    let q = 4 * mf;
    let (lo, hi) = match rc {
        0 => (if mf == 1 << 23 { q - 1 } else { q - 2 }, q + 2),
        1 | 3 => (q, q + 4),
        _ => (if mf == 1 << 23 { q - 2 } else { q - 4 }, q),
    };
    let (mut sum, mut sticky) = (0u128, false);
    for v in [x, y] {
        let (mv, ev) = parts(v);
        if mv == 0 {
            continue;
        }
        let sq = mv * mv;
        let k = 2 * (ev - ef) + 4 + 64;
        if k >= 0 {
            if k as u32 + 4 >= sq.leading_zeros() {
                return false; // this square alone is far above hi²
            }
            sum += sq << k;
        } else if -k >= 128 {
            sticky = true;
        } else {
            sum += sq >> -k;
            sticky |= sq & ((1u128 << -k) - 1) != 0;
        }
    }
    let (lo2, hi2) = ((lo * lo) << 64, (hi * hi) << 64);
    // The true root t has t² = sum + (a positive fraction iff sticky). An exact root t = f is
    // right in every direction: the directed intervals are closed at f (downward and toward
    // zero t >= f, upward t <= f), the nearest one is open at both midpoints.
    let above_lo = sum > lo2 || (sum == lo2 && (sticky || rc == 1 || rc == 3));
    let below_hi = sum < hi2 || (sum == hi2 && !sticky && rc == 2);
    above_lo && below_hi
}

#[test]
#[ignore = "exhaustive: cargo test -p liella-boundary --release --test s10_math_symbols -- --ignored --nocapture math_hypotf_fast_path_sweep"]
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn math_hypotf_fast_path_sweep() {
    // Clauses: s10_0_f_0. #1541: every float x (all 2^32 encodings) against nine second
    // operands (x itself and eight fixed ones), in the four directions: whenever the fast path
    // answers, the integer oracle confirms the correctly rounded result.
    use liella_boundary::mathret as mr;
    use std::sync::atomic::{AtomicU64, Ordering::Relaxed};
    let ys: [Option<f32>; 9] = [None, Some(1.0), Some(3.0), Some(0.1), Some(1.732_050_8), Some(f32::MIN_POSITIVE), Some(1e-40), Some(1e30), Some(f32::MAX)];
    let threads = std::thread::available_parallelism().map_or(4, |n| n.get());
    for y in ys {
        let (next, fast, bad) = (AtomicU64::new(0), AtomicU64::new(0), AtomicU64::new(0));
        std::thread::scope(|sc| {
            for _ in 0..threads {
                sc.spawn(|| loop {
                    let c = next.fetch_add(1, Relaxed);
                    if c >= 1 << 12 {
                        break;
                    }
                    let (mut nf, mut nb) = (0u64, 0u64);
                    for rc in 0..4u32 {
                        fpu::leave(&CSys, 0x1f80 | rc << 13);
                        for b in (c << 20) as u32..=((c << 20) | 0xf_ffff) as u32 {
                            let x = f32::from_bits(b);
                            let yv = y.unwrap_or(x);
                            if let Some(f) = mr::hypotf_fast(x, yv) {
                                nf += 1;
                                if !hypotf_oracle(x, yv, f, rc) {
                                    nb += 1;
                                    if nb < 4 {
                                        eprintln!("BAD hypotf({x:e}, {yv:e}) dir {rc} -> {f:e}");
                                    }
                                }
                            }
                        }
                    }
                    fpu::leave(&CSys, 0x1f80);
                    fast.fetch_add(nf, Relaxed);
                    bad.fetch_add(nb, Relaxed);
                });
            }
        });
        let (nf, nb) = (fast.load(Relaxed), bad.load(Relaxed));
        println!("hypotf sweep y={y:?}: calls {} fast {nf} fallback {} bad {nb}", 4u64 << 32, (4u64 << 32) - nf);
        assert_eq!(nb, 0, "fast path results off the oracle for y={y:?}");
    }
    // Timing (informational): the entry against the accurate path on random normal operands.
    let v: Vec<(f32, f32)> = (1..=1u32 << 20).map(|i| (f32::from_bits(0x3f80_0000 ^ i.wrapping_mul(0x9e37_79b9) >> 9), f32::from_bits(0x4000_0000 ^ i.wrapping_mul(0x85eb_ca6b) >> 9))).collect();
    let t = std::time::Instant::now();
    let a: f32 = v.iter().map(|&(x, y)| m::hypotf(std::hint::black_box(x), y)).sum();
    let t_fast = t.elapsed().as_nanos() as f64 / v.len() as f64;
    let t = std::time::Instant::now();
    let b: f32 = v.iter().map(|&(x, y)| mr::ret(liella_math::pow::hypot(std::hint::black_box(x), y, mr::mode()))).sum();
    let t_acc = t.elapsed().as_nanos() as f64 / v.len() as f64;
    println!("hypotf timing: entry {t_fast:.1} ns/call, accurate path {t_acc:.1} ns/call ({a} {b})");
    fpu::clear(&CSys, Flags::ALL);
}
